#!/usr/bin/env node
/**
 * Minimal driver for the bridge-mode role. The fixture's own driver drives the
 * served MCP registry with the official client and never starts the product, so
 * this one boots the same composition and triggers bridge mode once instead:
 * `subagents.start('claude-code', { harnessTools: { only: true } })` serves the
 * child harness agent's registry to the external model and executes every call
 * it makes through the harness executor.
 */

import { writeFile } from 'node:fs/promises'
import { join } from 'node:path'
import { boot, resolveConfigPath } from '@deepseek-ai/dsh-app-boot'
import type {} from '@deepseek-ai/cordis-plugin-loader'
import type {} from '@deepseek-ai/dsh-subagent'
import type {} from '@deepseek-ai/dsh-subagent-claude-code'
import { SessionId } from '@deepseek-ai/dsh-session'
import type { SessionEvent } from '@deepseek-ai/dsh-session'

const configPath = process.argv[2]
if (configPath === undefined) throw new Error('bridge driver requires a config path')

const ctx = await boot('agent-bridge-role', resolveConfigPath(configPath, undefined))
try {
  await ctx.get('loader')?.await()
  const subagents = ctx.get('subagents')
  if (subagents === undefined) throw new Error('bridge driver requires the subagents service')

  for (const name of ['alpha.txt', 'beta.txt', 'gamma.txt']) {
    await writeFile(join(process.cwd(), name), `${name}\n`)
  }

  const parent = await ctx.agents.create({
    sessionId: SessionId('bridge-parent'),
    meta: { cwd: process.cwd() },
    agentOptions: { provider: 'cli-mock', model: 'cli-mock' },
  })
  try {
    const run = await subagents.start('claude-code', {
      prompt: [{
        type: 'text',
        text: 'Read the file alpha.txt in the working directory and reply with its exact contents. '
          + 'Use only the tools you were given.',
      }],
      parent: parent.agent,
      signal: AbortSignal.timeout(600_000),
      harnessTools: { only: true },
    })
    const result = await run.result
    const child = run.localAgent
    const events = child?.session.events ?? []
    process.stdout.write(`${JSON.stringify({
      type: 'result',
      stopReason: result.stopReason,
      text: result.text,
      childSessionId: child?.session.id ?? null,
      eventTypes: events.map((event: SessionEvent) => event.type),
      bridge: events.flatMap((event: SessionEvent) => (
        event.type.startsWith('bridge/') ? [{ type: event.type, data: event.data }] : []
      )),
      toolCalls: events.flatMap((event: SessionEvent) => (
        event.type === 'tool/call' ? [{ name: event.data.name, arguments: event.data.arguments }] : []
      )),
      toolResults: events.flatMap((event: SessionEvent) => (
        event.type === 'tool/result'
          ? [{ isError: event.data.message.content[0].isError === true }]
          : []
      )),
    })}\n`)
    await run.dispose()
    process.stdout.write(`${JSON.stringify({
      type: 'closed',
      eventTypes: (child?.session.events ?? []).map((event: SessionEvent) => event.type),
    })}\n`)
  } finally {
    await parent.dispose()
  }
} finally {
  await ctx.fiber.dispose()
}
EOF
